// PLAN:
// 1) Composition: full-bleed 7x5.5 gradient plate at z=-0.06; left-aligned column at x=-3.1 — kicker y=1.7, two hero lines y=0.9/0.25, red rule y=-0.15, body y=-0.8, caption y=-1.9; letterpress shadow copies of hero 0.02 behind.
// 2) Light rig: rig-dusk-editorial — warm key dir #ffc890 @2.8, fill point #b9a68e @3, rim dir #f2f4f6 @1.7, ambient 0.09 (grades the plate; type is MSDF unlit).
// 3) Materials: plate = MeshStandardNodeMaterial with TSL vertical gradient #0b0b10->#14141a + 1.5% monochrome grain, roughness 0.62 metalness 0.2; rule = emissive #ff2a38 @1.2.
// 4) Motion: rise-in per block top-to-bottom (y+0.4->0, fade, 0.7s power3.out, 80ms stagger); rule draws scaleX 0->1 over 0.5s power2.out after hero lands. No idle multi-axis motion.
// 5) Focal element: the stacked Lora hero "PRECISION IS / A HABIT." in paper #e8ecf2 — brightest read on the frame.
import {
  Group,
  Mesh,
  PlaneGeometry,
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
  DirectionalLight,
  PointLight,
  AmbientLight,
  Color,
} from 'three/webgpu';
import { uv, vec3, mix, fract, sin, dot, vec2, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new Group();
  root.name = 'editorial-oversized-type';

  const colors =
    config.intent?.visualSpec?.colors ?? {
      background: '#0b0b10',
      surface: '#14141a',
      ink: '#16161d',
      paper: '#e8ecf2',
      accent: '#ff2a38',
    };

  const disposables = [];
  const timelines = [];

  // ---- backdropPlate: full-bleed 7 x 5.5 gradient plate with monochrome grain ----
  const plateGeo = new PlaneGeometry(7, 5.5);
  const plateMat = new MeshStandardNodeMaterial({ roughness: 0.62, metalness: 0.2 });
  {
    const bg = new Color(colors.background ?? '#0b0b10');
    const surf = new Color(colors.surface ?? '#14141a');
    const g = uv().y; // 0 bottom -> 1 top; gradient stop 0 = background at bottom
    const grad = mix(vec3(bg.r, bg.g, bg.b), vec3(surf.r, surf.g, surf.b), g);
    // 1.5% monochrome grain (engineered, static hash noise)
    const n = fract(sin(dot(uv().mul(vec2(912.7, 771.3)), vec2(12.9898, 78.233))).mul(43758.5453));
    plateMat.colorNode = grad.add(n.sub(0.5).mul(float(0.03)));
  }
  const plate = new Mesh(plateGeo, plateMat);
  plate.position.set(0, 0, -0.06);
  root.add(plate);
  disposables.push(plateGeo, plateMat);

  // ---- lightRig: rig-dusk-editorial ----
  const key = new DirectionalLight('#ffc890', 2.8);
  key.position.set(3, 0.9, 1.2);
  key.target.position.set(0, 0.4, 0);
  const fill = new PointLight('#b9a68e', 3, 9, 2);
  fill.position.set(-2.4, 0.6, 1.8);
  const rim = new DirectionalLight('#f2f4f6', 1.7);
  rim.position.set(-1.8, 2.8, -2);
  rim.target.position.set(0, 0.6, 0);
  const ambient = new AmbientLight('#ffffff', 0.09);
  root.add(key, key.target, fill, rim, rim.target, ambient);

  // ---- textColumn ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const byRole = (role) => items.filter((i) => i.role === role);
  const LEFT_X = -3.1;
  const blocks = []; // groups for staggered rise-in, top-to-bottom

  function addBlock(obj, y) {
    const g = new Group();
    g.add(obj);
    g.position.set(LEFT_X, y, 0);
    root.add(g);
    blocks.push(g);
    return g;
  }

  // kickerText
  const kickerItem = byRole('kicker')[0];
  if (kickerItem) {
    const t = ctx.fontAtlas.createText(String(kickerItem.text), {
      fontSize: kickerItem.typography?.fontSize ?? 18,
      color: colors.paper ?? '#e8ecf2',
      align: 'left',
      letterSpacingPx: 2.2, // 0.12em tracking
    });
    addBlock(t, 1.7);
  }

  // heroLines (+ letterpress ink shadow copies 0.02 behind)
  const heroItems = byRole('hero');
  const heroYs = [0.9, 0.25];
  heroItems.slice(0, 2).forEach((item, i) => {
    const shadow = ctx.fontAtlas.createText(String(item.text), {
      fontSize: item.typography?.fontSize ?? 124,
      color: colors.ink ?? '#16161d',
      align: 'left',
      letterSpacingPx: -1.9, // -0.015em
    });
    shadow.position.set(0.012, -0.012, -0.02); // print-depth letterpress edge
    const face = ctx.fontAtlas.createText(String(item.text), {
      fontSize: item.typography?.fontSize ?? 124,
      color: colors.paper ?? '#e8ecf2',
      align: 'left',
      letterSpacingPx: -1.9,
    });
    const line = new Group();
    line.add(shadow, face);
    addBlock(line, heroYs[i]);
  });

  // accentRule: 2.2 x 0.05 emissive signal-red rule
  const ruleGeo = new PlaneGeometry(2.2, 0.05);
  const accent = new Color(colors.accent ?? '#ff2a38');
  const ruleMat = new MeshBasicNodeMaterial();
  ruleMat.colorNode = vec3(accent.r, accent.g, accent.b).mul(float(1.2));
  const rule = new Mesh(ruleGeo, ruleMat);
  rule.geometry.translate(1.1, 0, 0); // scaleX draws from left edge
  const ruleGroup = new Group();
  ruleGroup.add(rule);
  ruleGroup.position.set(LEFT_X, -0.15, 0.005);
  ruleGroup.scale.x = 0.0001;
  root.add(ruleGroup);
  disposables.push(ruleGeo, ruleMat);

  // bodyText
  const bodyItem = byRole('body')[0];
  if (bodyItem) {
    const t = ctx.fontAtlas.createText(String(bodyItem.text), {
      fontSize: bodyItem.typography?.fontSize ?? 26,
      color: colors.paper ?? '#e8ecf2',
      align: 'left',
      maxWidthPx: 660, // ~4.5 scene units max width
    });
    addBlock(t, -0.8);
  }

  // captionText
  const captionItem = byRole('caption')[0];
  if (captionItem) {
    const t = ctx.fontAtlas.createText(String(captionItem.text), {
      fontSize: captionItem.typography?.fontSize ?? 18,
      color: colors.paper ?? '#e8ecf2',
      align: 'left',
      letterSpacingPx: 1.4, // 0.08em
    });
    addBlock(t, -1.9);
  }

  // ---- entranceMotion: rise-in stagger top-to-bottom, then rule draw ----
  const tl = gsap.timeline();
  blocks.forEach((g, i) => {
    const targetY = g.position.y;
    g.position.y = targetY + 0.4;
    g.visible = false;
    tl.to(
      g.position,
      { y: targetY, duration: 0.7, ease: 'power3.out' },
      i * 0.08
    ).set(g, { visible: true }, i * 0.08);
    // fade via per-mesh material opacity where available
    g.traverse((o) => {
      if (o.material && 'opacity' in o.material) {
        o.material.transparent = true;
        const target = o.material.opacity ?? 1;
        o.material.opacity = 0;
        tl.to(o.material, { opacity: target, duration: 0.7, ease: 'power2.out' }, i * 0.08);
      }
    });
  });
  // rule draws after hero lands (hero blocks are indices 1-2; land ~0.08*2+0.7)
  tl.to(ruleGroup.scale, { x: 1, duration: 0.5, ease: 'power2.out' }, 0.9);
  timelines.push(tl);

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    disposables.forEach((d) => d.dispose && d.dispose());
    root.traverse((o) => {
      if (o.geometry && !disposables.includes(o.geometry)) o.geometry.dispose?.();
      if (o.material && !disposables.includes(o.material)) {
        o.material.map?.dispose?.();
        o.material.dispose?.();
      }
    });
  };

  return root;
}

