{"elements":[
{"id":"text.kicker.0","where":"kickerText","how":"fontAtlas kicker at y=1.7, tracked caps"},
{"id":"text.hero.1","where":"heroLines","how":"Lora hero line 1 at y=0.9"},
{"id":"text.hero.2","where":"heroLines","how":"Lora hero line 2 at y=0.25"},
{"id":"text.body.3","where":"bodyText","how":"body paragraph maxWidth at y=-0.8"},
{"id":"text.caption.4","where":"captionText","how":"caption at y=-1.9"},
{"id":"color.background","where":"backdropPlate","how":"gradient stop 0 #0b0b10"},
{"id":"color.surface","where":"backdropPlate","how":"gradient stop 1 #14141a"},
{"id":"color.ink","where":"heroLines","how":"letterpress shadow copies #16161d"},
{"id":"color.paper","where":"textColumn","how":"all foreground type #e8ecf2"},
{"id":"color.accent","where":"accentRule","how":"emissive 1.2 red rule"},
{"id":"color.gradient","where":"backdropPlate","how":"TSL vertical mix of two stops"},
{"id":"effects.spec","where":"createNode","how":"7x5.5 plate, grain, grid, letterpress, entrance"}
]}
*/
